(function(E){ const x = E["ai-m3"] = E["ai-m3"] || {units:{}}; x.units["ai-11"] = {"grammar":{"id":"c-ai-11-g","level":"B1","course":"ai-internet","unit":"ai-11","title":"Plain versions of inflated phrases","titleTr":"Şişirilmiş ifadelerin sade hâli","titleFa":"شکل ساده‌ی عبارت‌های پرطمطراق","formsTable":{"headers":{"en":["Stiff","Plain"],"tr":["Katı","Sade"],"fa":["خشک","ساده"]},"rows":[["We regret to inform you","I'm sorry to tell you"],["leverage","use"],["at your earliest convenience","by Friday, if you can"],["in the event that","if"]]},"wrong":"We regret to inform you that it is delayed.","right":"I'm sorry to tell you that it is delayed.","blank":{"sentence":"We ___ this tool every day.","word":"use","distractors":["leverage of","are leveraging of"]},"wrong2":"Please reply at your earliest convenience.","right2":"Please reply by Friday, if you can.","blank2":{"sentence":"Please reply ___ Friday, if you can.","word":"by","distractors":["until to","at"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Choose the short common word.","tr":"Kısa ve yaygın kelimeyi seç.","fa":"کلمه‌ی کوتاه و رایج را انتخاب کن.","ex":"use, not leverage"},{"en":"Give a real time, not a vague phrase.","tr":"Belirsiz ifade değil, gerçek zaman ver.","fa":"به‌جای عبارت مبهم، زمان واقعی بده.","ex":"by Friday"}],"test":{"en":"Would you say it to a colleague?","tr":"Bunu bir meslektaşına söyler miydin?","fa":"این را به همکارت می‌گفتی؟"}},"errorWatch":[{"find":["leverage of"],"fix":{"en":"Use the plain word: \"use\".","tr":"Sade kelimeyi kullan: \"use\".","fa":"کلمه‌ی ساده را به کار ببر: «use»."}}]},"b2":{"id":"c-ai-11-b2","level":"B2","course":"ai-internet","unit":"ai-11","track":"B2","title":"Honest notes: I used AI to, then I checked","titleTr":"Dürüst notlar: I used AI to, then I checked","titleFa":"یادداشت صادقانه: I used AI to، then I checked","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["I used AI to + verb","I used AI to draft this report."],["Then I checked X against Y","Then I checked the figures against the sheet."]]},"wrong":"I used AI for draft this report.","right":"I used AI to draft this report.","blank":{"sentence":"I used AI ___ draft this reply.","word":"to","distractors":["for","by"]},"wrong2":"Then I checked the figures to the sheet.","right2":"Then I checked the figures against the sheet.","blank2":{"sentence":"I checked the dates ___ the order sheet.","word":"against","distractors":["to","on"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Say what AI did, with to + verb.","tr":"Yapay zekânın ne yaptığını to + fiil ile söyle.","fa":"با to + فعل بگو هوش مصنوعی چه کرد.","ex":"I used AI to shorten it."},{"en":"Say what you did after that.","tr":"Sonra ne yaptığını söyle.","fa":"بگو بعدش خودت چه کردی.","ex":"Then I checked the dates."}],"test":{"en":"Did you say what you checked?","tr":"Neyi kontrol ettiğini söyledin mi?","fa":"گفته‌ای چه چیزی را بررسی کردی؟"}},"errorWatch":[{"find":["used ai for draft"],"fix":{"en":"Use \"used AI to + verb\".","tr":"\"used AI to + fiil\" kullan.","fa":"از «used AI to + فعل» استفاده کن."}}],"useIn":{"en":"B2: end your change note with one honest sentence about how you used AI.","tr":"B2: Değişiklik notunu yapay zekâyı nasıl kullandığını anlatan dürüst bir cümleyle bitir.","fa":"B2: یادداشت تغییرت را با جمله‌ای صادقانه درباره‌ی نحوه‌ی استفاده از هوش مصنوعی تمام کن."},"exitItem":{"from":"ai-11","kind":"blank","prompt":"I used AI ___ shorten the report.","options":["to","for","by"],"correct":0}},"vocab":{"id":"c-ai-11-v","level":"B1","category":"vocab","course":"ai-internet","unit":"ai-11","goals":["career"],"title":{"en":"Plain and clear","tr":"Sade ve net","fa":"ساده و روشن"},"cards":[{"word":"stiff","sentence":"This email sounds stiff.","meaning":{"en":"Too formal, not natural.","tr":"Fazla resmî, doğal olmayan.","fa":"بیش از حد رسمی، نه طبیعی."}},{"word":"plain English","sentence":"Please write it in plain English.","meaning":{"en":"Simple, clear English.","tr":"Basit, net İngilizce.","fa":"انگلیسی ساده و روشن."}},{"word":"voice","sentence":"Keep our company's voice.","meaning":{"en":"The way a person or company always sounds.","tr":"Bir kişinin ya da şirketin hep kullandığı anlatım biçimi.","fa":"جوری که یک آدم یا شرکت همیشه حرف می‌زند."}},{"word":"change note","sentence":"Add a short change note.","meaning":{"en":"A note that says what you changed.","tr":"Neyi değiştirdiğini söyleyen not.","fa":"یادداشتی که می‌گوید چه چیزی را عوض کردی."}}]},"judge":{"id":"c-ai-11-j","course":"ai-internet","unit":"ai-11","type":"judge","title":{"en":"Is this line ready to send?","tr":"Bu satır göndermeye hazır mı?","fa":"این خط برای فرستادن آماده است؟"},"prompt":"Read each example AI line. What does it do well?","parts":["Plain","Answers the question","Keeps the numbers"],"instruction":{"en":"The customer asked: \"Can I get my 40 euro refund this week?\" Tap what each line does well.","tr":"Müşteri sordu: \"Can I get my 40 euro refund this week?\" Her satırın iyi yaptığına dokun.","fa":"مشتری پرسید: «Can I get my 40 euro refund this week?» روی چیزی که هر خط خوب انجام داده بزن."},"items":[{"by":"Example AI answer","answer":"We regret to inform you that reimbursement is being processed.","present":[],"fix":{"en":"Stiff, and no time or amount.","tr":"Katı; zaman ve tutar yok.","fa":"خشک است؛ نه زمان دارد نه مبلغ."}},{"by":"Example AI answer","answer":"Yes, your refund will be sent soon.","present":["Plain","Answers the question"],"fix":{"en":"Add the amount and a real day.","tr":"Tutarı ve gerçek bir gün ekle.","fa":"مبلغ و یک روز واقعی را اضافه کن."}},{"by":"Good model","answer":"Yes. We will send your 40 euro refund by Friday.","present":["Plain","Answers the question","Keeps the numbers"],"fix":null},{"by":"Example AI answer","answer":"Your 40 euro refund is in the system.","present":["Plain","Keeps the numbers"],"fix":{"en":"It doesn't say when, and that was the question.","tr":"Ne zaman olduğunu söylemiyor, soru da buydu.","fa":"نمی‌گوید کی، و سؤال همین بود."}}]},"branch":{"id":"c-ai-11-br","course":"ai-internet","unit":"ai-11","type":"branch","title":{"en":"Your manager asks about a draft","tr":"Yöneticin bir taslağı soruyor","fa":"مدیرت درباره‌ی یک پیش‌نویس می‌پرسد"},"setting":{"en":"A short chat at work. Choose what you say.","tr":"İş yerinde kısa bir sohbet. Ne söyleyeceğini seç.","fa":"یک گفت‌وگوی کوتاه در محل کار. انتخاب کن چه بگویی."},"start":"n1","nodes":{"n1":{"speaker":"Manager","line":"This email is very good. Did you write it yourself?","choices":[{"tone":"good","text":"I used AI to draft it, then I rewrote it in plain English.","next":"n2","reply":"Good to know.","feedback":{"en":"Honest, and it says what you did.","tr":"Dürüst ve ne yaptığını söylüyor.","fa":"صادقانه است و می‌گوید چه کردی."}},{"tone":"ok","text":"I had some help from a tool.","next":"n2","reply":"What kind of help?","feedback":{"en":"True, but say what the tool did.","tr":"Doğru ama aracın ne yaptığını söyle.","fa":"درست است، ولی بگو ابزار چه کرد."}},{"tone":"poor","text":"Yes, all of it.","next":"n1","reply":"Really? All of it?","feedback":{"en":"That isn't true, and it may come out later.","tr":"Bu doğru değil, sonradan ortaya çıkabilir.","fa":"این درست نیست و ممکن است بعداً معلوم شود."}}]},"n2":{"speaker":"Manager","line":"How do I know the numbers are right?","choices":[{"tone":"good","text":"I checked them against the order sheet, line by line.","next":"end","reply":"Thanks. Please send it.","feedback":{"en":"It names the source and the method.","tr":"Kaynağı ve yöntemi söylüyor.","fa":"منبع و روش را می‌گوید."}},{"tone":"ok","text":"I read them twice.","next":"end","reply":"OK. Next time, check the sheet too.","feedback":{"en":"Reading is good, but a source is proof.","tr":"Okumak iyi ama kanıt kaynaktır.","fa":"خواندن خوب است، ولی دلیل منبع است."}},{"tone":"poor","text":"The tool is usually right.","next":"n2","reply":"Usually?","feedback":{"en":"A tool is not a source. Check it.","tr":"Araç kaynak değildir. Kontrol et.","fa":"ابزار منبع نیست. بررسی کن."}}]},"end":{"end":true,"outcome":{"en":"You were honest about the tool, and you could show your check.","tr":"Araç konusunda dürüst oldun ve kontrolünü gösterebildin.","fa":"درباره‌ی ابزار صادق بودی و توانستی بررسی‌ات را نشان بدهی."}}}},"speaking":{"id":"ai-11","course":"ai-internet","unit":"ai-11","topic":{"en":"Say how you used AI","tr":"Yapay zekâyı nasıl kullandığını söyle","fa":"بگو چطور از هوش مصنوعی استفاده کردی"},"warmup":{"en":"Which words in work emails do you never use yourself?","tr":"İş e-postalarında kendin hiç kullanmadığın kelimeler hangileri?","fa":"کدام کلمه‌های ایمیل کاری را خودت هیچ‌وقت به کار نمی‌بری؟"},"questions":[{"en":"Tell a colleague how you used AI on one piece of work, and what you checked.","tr":"Bir meslektaşına bir işte yapay zekâyı nasıl kullandığını ve neyi kontrol ettiğini anlat.","fa":"به همکارت بگو در یک کار چطور از هوش مصنوعی استفاده کردی و چه چیزی را بررسی کردی."},{"en":"A customer asks: \"Did a person write this email?\" Answer honestly.","tr":"Bir müşteri soruyor: \"Did a person write this email?\" Dürüstçe yanıtla.","fa":"مشتری می‌پرسد: «Did a person write this email?» صادقانه جواب بده."},{"en":"Say this in plain English: \"We regret to inform you that delivery shall be delayed.\"","tr":"Bunu sade İngilizceyle söyle: \"We regret to inform you that delivery shall be delayed.\"","fa":"این را به انگلیسی ساده بگو: «We regret to inform you that delivery shall be delayed.»"}],"followups":[{"en":"Now say it again about your own work. Use made-up names and numbers.","tr":"Şimdi aynısını kendi işin için söyle. Uydurma ad ve sayılar kullan.","fa":"حالا همین را درباره‌ی کار خودت بگو. از نام‌ها و عددهای ساختگی استفاده کن."}],"expressions":[{"phrase":"I used AI to...","meaning":{"en":"Says what the tool did.","tr":"Aracın ne yaptığını söyler.","fa":"می‌گوید ابزار چه کرد."}},{"phrase":"Then I checked...","meaning":{"en":"Says what you did.","tr":"Senin ne yaptığını söyler.","fa":"می‌گوید تو چه کردی."}}],"model":"I used AI to draft the email to our supplier, because I wanted a first version quickly. The problem is that it sounded very stiff, so I rewrote it in plain English. Then I checked the dates and the prices against the order. I took out two sentences I couldn't explain. It's my name on the email, so I wanted it to sound like me.","selfCheck":[{"en":"I did every point of the task.","tr":"Görevin her noktasını yaptım.","fa":"همه‌ی نکته‌های تمرین را انجام دادم."},{"en":"I used at least two phrases from this lesson.","tr":"Bu dersten en az iki ifade kullandım.","fa":"دست‌کم دو عبارت از این درس به کار بردم."},{"en":"I spoke in short, clear sentences.","tr":"Kısa ve net cümlelerle konuştum.","fa":"با جمله‌های کوتاه و روشن حرف زدم."},{"en":"I said what I checked.","tr":"Neyi kontrol ettiğimi söyledim.","fa":"گفتم چه چیزی را بررسی کردم."}]},"writing":{"id":"c-ai-11-w","title":{"en":"Rewrite a stiff email","tr":"Katı bir e-postayı yeniden yaz","fa":"یک ایمیل خشک را بازنویسی کن"},"course":"ai-internet","unit":"ai-11","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"ai-final-2","prompt":{"en":"Rewrite this AI email in plain English, keep the numbers, and write a one-line change note: \"We regret to inform you that the 200 units shall be dispatched on 8 May. Kindly advise at your earliest convenience should this be unsatisfactory.\" Ask for an answer by Friday.","tr":"Bu yapay zekâ e-postasını sade İngilizceyle yeniden yaz, sayıları koru ve tek satırlık değişiklik notu yaz: \"We regret to inform you that the 200 units shall be dispatched on 8 May. Kindly advise at your earliest convenience should this be unsatisfactory.\" Cevabı cuma gününe kadar iste.","fa":"این ایمیل هوش مصنوعی را به انگلیسی ساده بازنویسی کن، عددها را نگه دار و یک خط یادداشت تغییر بنویس: «We regret to inform you that the 200 units shall be dispatched on 8 May. Kindly advise at your earliest convenience should this be unsatisfactory.» جواب را تا جمعه بخواه."},"model":"I'm sorry to tell you that we will send the 200 units on 8 May. If this is a problem, please tell me by Friday.\n\nChange note: I used AI to draft this, then I made it plainer and kept the number and the date.","frame":"I'm sorry to tell you that ___. If this is a problem, please tell me by ___.\n\nChange note: I used AI to ___, then I ___.","words":[{"word":"I'm sorry to tell you"},{"word":"I used AI to"}],"minWords":30,"minSentences":2,"rubric":["Task done: every point of the task is there","Organised: clear parts, in a sensible order","Language: the phrases of this lesson, used correctly","Tone: clear and honest; nothing you cannot explain"],"rubricI18n":{"tr":["Görev: görevin her noktası var","Düzen: açık bölümler, mantıklı sıra","Dil: bu dersin ifadeleri, doğru kullanılmış","Üslup: açık ve dürüst; açıklayamayacağın bir şey yok"],"fa":["کامل بودن کار: همه‌ی نکته‌های تمرین آمده","نظم: بخش‌های روشن، با ترتیب منطقی","زبان: عبارت‌های این درس، درست به کار رفته","لحن: روشن و صادق؛ چیزی که نتوانی توضیح بدهی در آن نیست"]},"b2Task":{"en":"B2 track: no frame. Match the tone to a long-term customer and keep one sentence of your own style.","tr":"B2 yolu: hazır çerçeve yok. Üslubu eski bir müşteriye uydur ve kendi tarzından bir cümle koru.","fa":"مسیر B2: چارچوب آماده نداری. لحن را با مشتری قدیمی هماهنگ کن و یک جمله با سبک خودت نگه دار."},"own":{"en":"Now rewrite a stiff email from your own work, with made-up details.","tr":"Şimdi işinden katı bir e-postayı uydurma ayrıntılarla yeniden yaz.","fa":"حالا یک ایمیل خشک از کار خودت را با جزئیات ساختگی بازنویسی کن."},"routes":[{"t":{"en":"I use an AI tool","tr":"Bir yapay zekâ aracı kullanıyorum","fa":"از یک ابزار هوش مصنوعی استفاده می‌کنم"},"s":{"en":"Give your tool the rewrite prompt and a short sample of your writing. Then apply the explain test.","tr":"Aracına yeniden yazma prompt'unu ve yazından kısa bir örnek ver. Sonra açıklama testini uygula.","fa":"پرامپت بازنویسی و نمونه‌ی کوتاهی از نوشته‌ات را به ابزار بده. بعد آزمون توضیح را اجرا کن."}},{"t":{"en":"I don't have a tool","tr":"Bir aracım yok","fa":"ابزاری ندارم"},"s":{"en":"Use the example email above, and do the rewrite yourself.","tr":"Yukarıdaki örnek e-postayı kullan ve yeniden yazmayı kendin yap.","fa":"از ایمیل نمونه‌ی بالا استفاده کن و بازنویسی را خودت انجام بده."},"noTool":true}]},"exit":{"id":"c-ai-11-x","course":"ai-internet","unit":"ai-11","type":"exit","items":[{"from":"ai-11","kind":"mcq","prompt":"You can't explain a sentence in your draft. What do you do?","options":["Add a polite word.","Replace it.","Send it anyway."],"correct":1,"why":{"en":"Your name is on it.","tr":"Altında senin adın var.","fa":"اسم تو پای آن است."},"point":1},{"from":"ai-11","kind":"mcq","prompt":"What is a plain version of \"at your earliest convenience\"?","options":["with great pleasure","in the event that","by Friday, if you can"],"correct":2,"why":{"en":"Give a real time.","tr":"Gerçek bir zaman ver.","fa":"زمان واقعی بده."},"point":3},{"from":"ai-11","kind":"mcq","prompt":"What else do you check besides the words?","options":["Is it over one hundred words?","Did it answer their question?","Does it use long enough words?"],"correct":1,"why":{"en":"Check what is missing too.","tr":"Eksikleri de kontrol et.","fa":"چیزهای جاافتاده را هم بررسی کن."},"point":1},{"from":"ai-10","kind":"mcq","prompt":"The sheet says 10 days and the draft says 5. What is your result?","options":["Remove","Keep","Correct"],"correct":2,"why":{"en":"The source says something else.","tr":"Kaynak başka şey söylüyor.","fa":"منبع چیز دیگری می‌گوید."}},{"from":"ai-8","kind":"mcq","prompt":"In a chat tool, how do you keep the rest of a picture?","options":["Change only the background. Keep everything else.","Make a new picture with a new background each time.","Add --ar 16:9 and send the same prompt again."],"correct":0,"why":{"en":"One change at a time.","tr":"Her seferinde tek değişiklik.","fa":"هر بار یک تغییر."}},{"from":"ai-4","kind":"mcq","prompt":"Why is \"Under 60 words\" better than \"short\"?","options":["It is longer.","A number is clearer.","It is more polite."],"correct":1,"why":{"en":"The tool doesn't have to guess.","tr":"Araç tahmin etmek zorunda kalmaz.","fa":"ابزار لازم نیست حدس بزند."}}]},"explain":{"id":"c-ai-11-e","course":"ai-internet","unit":"ai-11","type":"explain","level":"B1","title":{"en":"Make it yours","tr":"Kendi sesine çevir","fa":"با لحن خودت بنویس"},"objective":{"en":"In this lesson you will learn to rewrite a stiff AI draft in plain English and say honestly how you used AI.","tr":"Bu derste katı bir yapay zekâ taslağını sade İngilizceyle yeniden yazmayı ve yapay zekâyı nasıl kullandığını dürüstçe söylemeyi öğreneceksin.","fa":"در این درس یاد می‌گیری پیش‌نویس خشک هوش مصنوعی را با انگلیسی ساده بازنویسی کنی و صادقانه بگویی از هوش مصنوعی چطور استفاده کردی."},"hook":{"en":"If you can't explain a sentence, don't send it. Your name is on it, not the tool's.","tr":"Bir cümleyi açıklayamıyorsan gönderme. Altında aracın değil, senin adın var.","fa":"اگر نمی‌توانی جمله‌ای را توضیح بدهی، نفرستش. اسم تو پای آن است، نه اسم ابزار."},"stats":[{"label":{"en":"Minutes","tr":"Dakika","fa":"دقیقه"},"value":"20"},{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Tasks","tr":"Görev","fa":"تمرین"},"value":"4"}],"points":[{"head":{"en":"The explain test","tr":"Açıklama testi","fa":"آزمون توضیح"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"AI drafts often sound stiff, because formal phrases are very likely words in business text. Your reader wants a person, and you must stand behind every line.","tr":"Yapay zekâ taslakları çoğu zaman katı görünür, çünkü iş metinlerinde resmî kalıplar çok olası kelimelerdir. Okuyucun bir insan ister ve sen her satırın arkasında durmalısın.","fa":"پیش‌نویس هوش مصنوعی اغلب خشک است، چون در متن‌های کاری عبارت‌های رسمی کلمه‌های خیلی محتملی‌اند. خواننده‌ات دنبال یک آدم است و تو باید پشت هر خط بایستی."},"steps":[{"en":"Read each sentence. Can you explain it? If not, replace it.","tr":"Her cümleyi oku. Açıklayabiliyor musun? Yoksa değiştir.","fa":"هر جمله را بخوان. می‌توانی توضیحش بدهی؟ اگر نه، عوضش کن.","ex":"\"We leverage our capabilities.\" Replace it."},{"en":"Check what is missing too. Did it answer their question?","tr":"Eksikleri de kontrol et. Sorularını yanıtladı mı?","fa":"چیزهای جاافتاده را هم بررسی کن. به سؤال آن‌ها جواب داده؟","ex":"They asked \"when?\". The draft says \"soon\"."}],"phrases":[{"phrase":"Rewrite this in plain English, B1 level. Keep every number. Sound like a helpful colleague.","meaning":{"en":"A prompt to copy. Add a sample of your own writing to match your style.","tr":"Kopyalanacak prompt. Üslubuna uyması için kendi yazından bir örnek ekle.","fa":"پرامپت برای کپی. برای هماهنگی با سبکت نمونه‌ای از نوشته‌ی خودت اضافه کن."},"copy":true}],"tip":{"en":"Don't rely on lists of \"AI words\". They date fast.","tr":"\"Yapay zekâ kelimeleri\" listelerine güvenme, çabuk eskirler.","fa":"به فهرست‌های «کلمه‌های هوش مصنوعی» تکیه نکن؛ زود کهنه می‌شوند."}},{"head":{"en":"Say honestly how you used it","tr":"Nasıl kullandığını dürüstçe söyle","fa":"صادقانه بگو چطور از آن استفاده کردی"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"Your name is on it, not the tool's. In 2024 a Canadian tribunal made Air Canada pay for wrong advice from its own chatbot, and said the company is responsible for its website.","tr":"Altında aracın değil, senin adın var. 2024'te Kanada'da bir kurul, kendi sohbet botunun yanlış bilgisi için Air Canada'ya ödeme yapmasını emretti ve sitesindeki bilgilerden şirketin sorumlu olduğunu söyledi.","fa":"اسم تو پای آن است، نه اسم ابزار. در سال ۲۰۲۴ مرجعی در کانادا شرکت ⁨Air Canada⁩ را به‌خاطر راهنمایی غلط چت‌بات خودش به پرداخت پول محکوم کرد و گفت شرکت مسئول اطلاعات سایتش است."},"steps":[{"en":"Say what AI did.","tr":"Yapay zekânın ne yaptığını söyle.","fa":"بگو هوش مصنوعی چه کرد.","ex":"I used AI to draft this."},{"en":"Say what you did.","tr":"Senin ne yaptığını söyle.","fa":"بگو خودت چه کردی.","ex":"Then I checked the dates against the order."},{"en":"Follow your company's rule on saying when AI was used.","tr":"Yapay zekâ kullanımını belirtme konusunda şirketinin kuralına uy.","fa":"درباره‌ی اعلام استفاده از هوش مصنوعی به مقررات شرکتت عمل کن.","ex":"Ask your manager if there is no rule."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Plain versions of inflated phrases","tr":"Şişirilmiş ifadelerin sade hâli","fa":"شکل ساده‌ی عبارت‌های پرطمطراق"},"steps":[{"en":"Choose the short common word.","tr":"Kısa ve yaygın kelimeyi seç.","fa":"کلمه‌ی کوتاه و رایج را انتخاب کن.","ex":"use, not leverage"},{"en":"Give a real time, not a vague phrase.","tr":"Belirsiz ifade değil, gerçek zaman ver.","fa":"به‌جای عبارت مبهم، زمان واقعی بده.","ex":"by Friday"}],"table":{"headers":{"en":["Stiff","Plain"],"tr":["Katı","Sade"],"fa":["خشک","ساده"]},"rows":[["We regret to inform you","I'm sorry to tell you"],["leverage","use"],["at your earliest convenience","by Friday, if you can"],["in the event that","if"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Make a stiff line plain","tr":"Katı bir satırı sadeleştir","fa":"یک خط خشک را ساده کن"},"item":"We regret to inform you that, in the event of a delay, we shall endeavour to notify you at your earliest convenience.\nReal time: you can tell them by Friday.","answer":"I'm sorry to tell you that your order may be late. If it is, I will tell you by Friday.","walk":[{"en":"Find the words you wouldn't say.","tr":"Söylemeyeceğin kelimeleri bul.","fa":"کلمه‌هایی را که نمی‌گویی پیدا کن."},{"en":"Use the plain version and a real time.","tr":"Sade hâli ve gerçek bir zaman kullan.","fa":"شکل ساده و زمان واقعی را بیاور."},{"en":"Check that the facts stay the same.","tr":"Bilgilerin aynı kaldığını kontrol et.","fa":"بررسی کن اطلاعات تغییر نکرده باشد."}]},"quick":{"prompt":"Which sentence would you say to a customer?","options":["We shall endeavour to rectify this.","I'll fix this by Friday.","Rectification is forthcoming."],"correct":1,"why":{"en":"It is short, plain and gives a real time.","tr":"Kısa, sade ve gerçek zaman veriyor.","fa":"کوتاه و ساده است و زمان واقعی می‌دهد."}},"remember":{"en":"Never send English you can't explain.","tr":"Açıklayamadığın İngilizceyi asla gönderme.","fa":"هرگز انگلیسی‌ای را که نمی‌توانی توضیح بدهی نفرست."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر ⁨B2⁩"},"head":{"en":"Honest notes: I used AI to, then I checked","tr":"Dürüst notlar: I used AI to, then I checked","fa":"یادداشت صادقانه: ⁨I used AI to⁩، ⁨then I checked⁩"},"steps":[{"en":"Say what AI did, with to + verb.","tr":"Yapay zekânın ne yaptığını to + fiil ile söyle.","fa":"با ⁨to⁩ + فعل بگو هوش مصنوعی چه کرد.","ex":"I used AI to shorten it."},{"en":"Say what you did after that.","tr":"Sonra ne yaptığını söyle.","fa":"بگو بعدش خودت چه کردی.","ex":"Then I checked the dates."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["I used AI to + verb","I used AI to draft this report."],["Then I checked X against Y","Then I checked the figures against the sheet."]]},"body":{"en":"B2: end your change note with one honest sentence about how you used AI.","tr":"B2: Değişiklik notunu yapay zekâyı nasıl kullandığını anlatan dürüst bir cümleyle bitir.","fa":"⁨B2⁩: یادداشت تغییرت را با جمله‌ای صادقانه درباره‌ی نحوه‌ی استفاده از هوش مصنوعی تمام کن."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
